  "condition": "relations_joint",
  "programs": [
    {
      "features": [],
      "name": "bounded_weighted_degree",
      "rationale": "Keeps conflict count dominant while adjusting for rival reward relative to the root. Uses native active-neighborhood aggregates with no added graph operations; mutual conflicts among rivals remain unmodeled.",
      "rule": "weight / (1 + 0.85 * degree + 0.15 * conflict_weight / (1 + weight))"
    },
