      "name": "continuous_turnaround_density",
      "rationale": "Scores reward per duration plus continuous turnaround overhead, subtracting a bounded conflict-count penalty. Uses only native inputs; occupancy efficiency can differ from displaced schedule reward and ignores rival overlap.",
      "rule": "weight / (1 + duration + 0.1 * (station_gap + satellite_gap)) - 0.12 * degree / (1 + degree)"
    },
    {
      "features": [],
      "name": "peak_gated_pressure_blend",
      "rationale": "Uses count efficiency when the root matches or exceeds its strongest rival; otherwise blends in weighted competition. This root-local conditional adds no feature scans, but strongest-rival dominance does not establish an inclusion certificate.",
      "rule": "weight / (1 + degree) if weight >= max_conflict_weight else 0.9 * weight / (1 + degree) + 0.1 * weight * (1 + weight) / (1 + weight + conflict_weight)"
    },
