        }
      ],
      "name": "capped_neighborhood_clustering",
      "rationale": "Discounts effective conflict count by at most fifteen percent when active rivals conflict among themselves. Reach stays within the root neighborhood; induced-edge enumeration can be quadratic, and clustering need not represent recoverable reward.",
      "rule": "weight / (1 + degree * (1 - 0.15 * min(1, rival_mean_internal_degree / max(1, degree - 1))))"
